CREATE TABLE companies(id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', vat_registered INTEGER NOT NULL DEFAULT 0 CHECK(vat_registered IN (0,1)), vat_number TEXT NOT NULL DEFAULT '', vat_bps INTEGER NOT NULL DEFAULT 1500 CHECK(vat_bps BETWEEN 0 AND 10000), next_job INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','dispatcher','technician')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE customers(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id));
CREATE TABLE properties(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, customer_id TEXT NOT NULL, label TEXT NOT NULL, address TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,customer_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
CREATE TABLE teams(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(company_id,id));
CREATE TABLE team_members(company_id TEXT NOT NULL, team_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(team_id,user_id), FOREIGN KEY(company_id,team_id) REFERENCES teams(company_id,id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE TABLE jobs(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), reference TEXT NOT NULL, customer_id TEXT NOT NULL, property_id TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, urgency TEXT NOT NULL CHECK(urgency IN ('routine','urgent','emergency')), status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','scheduled','in_progress','completed','cancelled')), deadline TEXT, scheduled_start TEXT, scheduled_end TEXT, team_id TEXT, internal_notes TEXT NOT NULL DEFAULT '', cancellation_reason TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(company_id,id), UNIQUE(company_id,reference), FOREIGN KEY(company_id,customer_id,property_id) REFERENCES properties(company_id,customer_id,id), FOREIGN KEY(company_id,team_id) REFERENCES teams(company_id,id));
CREATE TABLE assignments(company_id TEXT NOT NULL, job_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(job_id,user_id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE TABLE jobcards(job_id TEXT PRIMARY KEY, company_id TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE files(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('before','after','attachment')), name TEXT NOT NULL, mime TEXT NOT NULL, bytes BLOB NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE quotes(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','accepted','rejected')), data TEXT NOT NULL, expires_at TEXT NOT NULL, token_hash TEXT UNIQUE, issued_at TEXT, decision_by TEXT, decision_at TEXT, decision_note TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE quote_revisions(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, quote_id TEXT NOT NULL, revision INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(quote_id,revision), FOREIGN KEY(company_id,quote_id) REFERENCES quotes(company_id,id));
CREATE TABLE activities(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id TEXT NOT NULL REFERENCES companies(id), job_id TEXT, customer_id TEXT, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
CREATE INDEX job_company_status ON jobs(company_id,status);
CREATE INDEX job_company_schedule ON jobs(company_id,scheduled_start);
CREATE INDEX assignment_user ON assignments(company_id,user_id);
CREATE INDEX activity_job ON activities(company_id,job_id,id);
CREATE INDEX file_job ON files(company_id,job_id);
CREATE INDEX session_expiry ON sessions(expires_at);
